// Tile pattern: offset brick tiles with Truchet arcs + bevel, optional uPattern texture per tile.
// uPattern is a plain sampler2D (no @param). If it is unbound/empty, the procedural base shows alone.
uniform sampler2D uPattern;
uniform float uTiles;       // @param 6.0 1 24
uniform float uSpeed;       // @param 0.15 0 2
uniform float uPatternMix;  // @param 0.75 0 1
uniform float uGrout;       // @param 0.05 0 0.3
uniform float uArcWidth;    // @param 0.09 0.01 0.3
uniform vec3  uColorA;      // @param #1E3A5F
uniform vec3  uColorB;      // @param #E8B04A
uniform vec3  uGroutColor;  // @param #0B0C10

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = uv * vec2(aspect, 1.0) * uTiles;
  p.x += iTime * uSpeed;
  p.x += 0.5 * mod(floor(p.y), 2.0);          // brick offset
  vec2 id = floor(p);
  vec2 f = fract(p);
  float h = hash(id);
  float h2 = hash(id + 17.31);

  // Procedural base: per-tile color + Truchet arcs
  vec3 tileCol = mix(uColorA, uColorB, smoothstep(0.15, 0.95, h) * 0.55);
  vec2 q = f - 0.5;
  if (h2 > 0.5) q.x = -q.x;
  float d = min(abs(length(q - 0.5) - 0.5), abs(length(q + 0.5) - 0.5));
  float aa = fwidth(d) + 1e-4;
  float arc = 1.0 - smoothstep(uArcWidth - aa, uArcWidth + aa, d);
  float glow = exp(-d * 18.0) * 0.25;
  vec3 base = mix(tileCol, uColorB, arc) + uColorB * glow;

  // Optional texture, sampled per tile with continuous gradients (no mip seams)
  vec4 tex = textureGrad(uPattern, f, dFdx(p), dFdy(p));
  vec4 probe = textureLod(uPattern, vec2(0.5), 0.0) + textureLod(uPattern, vec2(0.2, 0.7), 0.0)
             + textureLod(uPattern, vec2(0.8, 0.3), 0.0);
  float hasTex = smoothstep(0.002, 0.02, dot(probe, vec4(1.0)));
  vec3 texCol = tex.rgb * (0.65 + 0.7 * luma(base)) + base * 0.15;
  vec3 col = mix(base, texCol, clamp(uPatternMix * hasTex * tex.a, 0.0, 1.0));

  // Bevel + grout
  vec2 e2 = min(f, 1.0 - f);
  float e = min(e2.x, e2.y);
  float ea = fwidth(e) + 1e-4;
  float tileMask = smoothstep(uGrout - ea, uGrout + ea, e);
  float bevel = 1.0 - smoothstep(uGrout, uGrout + 0.08, e);
  float light = (f.y - f.x) * 0.5;              // light from top-left
  col *= 1.0 + bevel * light * 0.6;
  col *= 0.9 + 0.1 * h;
  col = mix(uGroutColor, col, tileMask);

  vec2 c = uv - 0.5;
  col *= 1.0 - 0.45 * dot(c, c);
  fragColor = vec4(col, 1.0);
}
